// Generates the hub's reader registry from the projects that exist, so a new
// `Lembaran.<Format>` appears in the app without anyone editing the hub.
// `--check` fails when the generated file is stale.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const TARGET = join(ROOT, 'Lembaran.App/src/feature/choose/registry.generated.ts');
const SKIP = new Set(['Lembaran.App', 'Lembaran.UI']);
const ORDER = ['pdf', 'docs', 'pptx', 'xlsx', 'csv'];

function collect() {
  return readdirSync(ROOT, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && /^Lembaran\.[A-Z]/.test(entry.name))
    .filter((entry) => !SKIP.has(entry.name))
    .map((entry) => {
      const manifest = join(ROOT, entry.name, 'package.json');
      if (!existsSync(manifest)) return null;
      const pkg = JSON.parse(readFileSync(manifest, 'utf8').replace(/^\uFEFF/, ''));
      const meta = pkg.lembaran;
      if (!meta?.slug || !pkg.scripts?.build) return null;
      return {
        id: meta.id ?? meta.slug,
        folder: entry.name,
        slug: meta.slug,
        name: meta.name ?? meta.slug,
        blurb: meta.blurb ?? '',
        extensions: meta.extensions ?? [],
        mimeTypes: meta.mimeTypes ?? [],
      };
    })
    .filter((item) => item !== null)
    .sort((a, b) => {
      const left = ORDER.indexOf(a.id);
      const right = ORDER.indexOf(b.id);
      if (left !== -1 && right !== -1) return left - right;
      if (left !== -1) return -1;
      if (right !== -1) return 1;
      return a.id.localeCompare(b.id);
    });
}

const quote = (value) => `'${String(value).replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`;
const list = (values) => `[${values.map(quote).join(', ')}]`;

const readers = collect();
const rows = readers
  .map(
    (reader) => `  {
    id: ${quote(reader.id)},
    folder: ${quote(reader.folder)},
    slug: ${quote(reader.slug)},
    name: ${quote(reader.name)},
    blurb: ${quote(reader.blurb)},
    extensions: ${list(reader.extensions)},
    mimeTypes: ${list(reader.mimeTypes)},
  },`,
  )
  .join('\n');

const file = `// Generated by scripts/gen-readers.mjs from the projects on disk. Do not edit.
// A reader appears here when its package.json declares a \`lembaran\` block and a build.

export interface BuiltReader {
  id: string;
  folder: string;
  slug: string;
  name: string;
  blurb: string;
  extensions: string[];
  mimeTypes: string[];
}

export const BUILT_READERS: BuiltReader[] = [
${rows}
];
`;

if (process.argv.includes('--check')) {
  const current = existsSync(TARGET) ? readFileSync(TARGET, 'utf8') : '';
  if (current.trim() !== file.trim()) {
    console.error('registry.generated.ts is stale. Run: npm run readers');
    process.exit(1);
  }
  console.log(`reader registry is current (${readers.length} built)`);
} else {
  writeFileSync(TARGET, file);
  console.log(`wrote the registry for ${readers.length} reader(s): ${readers.map((r) => r.slug).join(', ')}`);
}
